style.css:
@-moz-document domain("animekai.to") {
/* Global background */
  body {
    background: url("https://tse2.mm.bing.net/th/id/OIP.8nfDk0UO03qci8pFA1dFBgHaEK?rs=1&pid=ImgDetMain&o=7&rm=3") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #fff !important;
  }

  /* Overlay for readability */
  body::before {
    content: "";
    position: fixed;
    top: 0; left: 0;
    width: 100%; height: 100%;
    background: rgba(0,0,0,0.6); /* dark overlay */
    z-index: -1;
  }

  /* Main content boxes */
  .container, .main, .content, .anime-list, .episode-list {
    background: rgba(20,20,20,0.8) !important;
    border-radius: 8px !important;
    padding: 10px !important;
  }

  /* Links and titles */
  a, h1, h2, h3, h4, h5 {
    color: #ffd700 !important; /* gold pirate accent */
  }

  /* Buttons */
  button, .btn {
    background: linear-gradient(90deg, #ff0000, #ff9900, #ffd700) !important;
    color: #111 !important;
    border: none !important;
    border-radius: 6px !important;
    transition: transform 0.2s ease;
  }
  button:hover, .btn:hover {
    transform: scale(1.05);
  }

  /* Video player tweaks */
  video, .player {
    border: 2px solid #ffd700 !important;
    border-radius: 6px !important;
  }
}
